INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_ABILITY_HELP','+1 Culture in cities founded on Hills. Independently, +1 Science in cities with a Walls-class building.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_CIV_PEDIA','Inspired by the Chachapoya peoples of the cloud forests in northern Peru and their stone settlements. Guardian Yana is a fictional representative leader of these varied communities.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_STRATEGY','Found on hills near strong food tiles, build Terraces, and reinforce important hills with Cloud Sentinels. Build walls where the science and protection are both useful.');
