INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_FALLBACK_1','We have heard your terms.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_FIRST_GREETING_1','Welcome to Kuélap. You have climbed far to reach us. I hope your intentions are lighter than your armor.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_DECLAREWAR_1','You see a wall. We see a home. Come and learn the difference.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_DEFEATED_1','Our stones may fall. Our mountains will not.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_ATTACKED_1','You brought ladders to the clouds? How ambitious.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D034_TRADE_OFFER_1','We offer the treasures of the heights. Please do not ask us to deliver them downhill.');
